/* linaX(uno) busybox: the /bin commands as applets of one
 * multicall image (BusyBox style). The kernel's argv
 * convention is "<name> <args>"; main dispatches on the
 * name. The romfs holds one entry per applet name, all
 * pointing at this single image.
 *
 * All applet statics live in one union: only one applet
 * runs in a process, so their buffers overlay. The data
 * window is 256 bytes; the union is sized by the largest
 * applet (cc, 206 bytes).
 *
 * Generated by gen_busybox.py from the standalone applet
 * sources (ls.c, cat.c, ...), which are kept for reference. */
#include <string.h>
#include "unox.h"

static char bb_argv[40];

static union {
	struct {
		unsigned char bc[96];
		int bc_len;
		int err;
		int infd;
		int pb;
		int eof_seen;
		int tok;
		int tokval;
		int tokvar;
		char tokbuf[12];
		char strbuf[32];
		int str_len;
		char srcname[24];
		char outname[24];
	} cc;
	struct {
		unsigned char code[96];
		int code_len;
		int vars[26];
		int st[10];
		int sp;
		char path[24];
	} vm;
	struct {
		char arg[44];
		char name[17];
		char tok[12];
		char tok1[12];
		char buf[16];
		char psbuf[64];
	} g;
} U;

/* Copy the applet's argument string, truncating like
 * sys_argv did. src is a RAM string. */
static void argcpy(char *dst, const char *src, int max)
{
	int i = 0;

	while (src[i] && i < max - 1) {
		dst[i] = src[i];
		i++;
	}
	dst[i] = 0;
}


static const char *base(const char *p)
{
	const char *b = p;

	while (*p) {
		if (*p == '/')
			b = p + 1;
		p++;
	}
	return b;
}

static void parent_of(const char *p, char *out)
{
	int i = 0, last = -1;

	while (p[i]) {
		if (p[i] == '/')
			last = i;
		i++;
	}
	if (last <= 0) {
		out[0] = '/';
		out[1] = 0;
	} else {
		memcpy(out, p, last);
		out[last] = 0;
	}
}

static int app_ls(const char *args)
{
	int type, size, i;
	char par[32];
	int found_file = 0;

	argcpy(U.g.arg, args, (int)sizeof(U.g.arg));
	if (U.g.arg[0] == 0) {
		U.g.arg[0] = '/';
		U.g.arg[1] = 0;
	}

	/* a plain file is listed alone */
	for (i = 0; sys_readdir(i, U.g.name, &type, &size); i++) {
		if (strcmp(U.g.name, U.g.arg) == 0 && type != 2) {
			sys_write(1, U.g.name, (int)strlen(U.g.name));
			uputs("  ");
			uputd(size);
			uputs("\n");
			found_file = 1;
		}
	}
	if (found_file)
		return 0;

	for (i = 0; sys_readdir(i, U.g.name, &type, &size); i++) {
		const char *b;

		if (U.g.name[0] == '/' && U.g.name[1] == 0)
			continue;
		parent_of(U.g.name, par);
		if (strcmp(par, U.g.arg) != 0)
			continue;
		b = base(U.g.name);
		sys_write(1, b, (int)strlen(b));
		if (type == 2)
			uputs("/");
		else {
			uputs("  ");
			uputd(size);
		}
		uputs("\n");
	}
	return 0;
}

static int app_cat(const char *args)
{
	char buf[24];
	int fd, n;

	argcpy(U.g.arg, args, (int)sizeof(U.g.arg));
	if (U.g.arg[0] == 0) {
		uputs("cat: no file\n");
		return 1;
	}
	fd = sys_open(U.g.arg);
	if (fd < 0) {
		uputs("cat: cannot open ");
		sys_write(1, U.g.arg, (int)strlen(U.g.arg));
		uputs("\n");
		return 1;
	}
	while ((n = sys_read(fd, buf, sizeof(buf))) > 0)
		sys_write(1, buf, n);
	sys_close(fd);
	return 0;
}

static int app_echo(const char *args)
{
	argcpy(U.g.arg, args, (int)sizeof(U.g.arg));
	sys_write(1, U.g.arg, (int)strlen(U.g.arg));
	uputs("\n");
	return 0;
}

static int app_uname(const char *args)
{
	uputs("linaX(uno) 0.8 ATmega328P (SRAM 2K, flash 32K)\n");
	return 0;
}

static int app_ps(const char *args)
{
	int n;

	uputs("pid st ppid\n");
	n = sys_tasks(U.g.psbuf, sizeof(U.g.psbuf));
	if (n > 0)
		sys_write(1, U.g.psbuf, n);
	return 0;
}

/* linaX(uno) cc: a tiny C-subset compiler.
 * Reads source from a /tmp file (streamed, one char at a
 * time), emits stack-VM bytecode into a window buffer, and
 * writes a 'UB' executable: cc /tmp/a.c -> /tmp/a.out.
 *
 * Language: variables a-z (int16), decimal literals, string
 * literals in print, + - * / %, == != < > <= >=, unary -,
 * assignment, print expr; / print "str";, if/else, while,
 * { } blocks, wait ms; and pin p, v; statements.
 * Keywords: print if else while wait pin. */

/* bytecode ops (shared with vm.c) */
#define OP_HALT  0x00
#define OP_PUSH  0x01
#define OP_LOAD  0x02
#define OP_STORE 0x03
#define OP_ADD   0x04
#define OP_SUB   0x05
#define OP_MUL   0x06
#define OP_DIV   0x07
#define OP_MOD   0x08
#define OP_NEG   0x09
#define OP_EQ    0x0A
#define OP_NE    0x0B
#define OP_LT    0x0C
#define OP_GT    0x0D
#define OP_LE    0x0E
#define OP_GE    0x0F
#define OP_JZ    0x10
#define OP_JMP   0x11
#define OP_PRINT 0x12
#define OP_PSTR  0x13
#define OP_WAIT  0x14
#define OP_PINW  0x15

#define BC_MAX 96


static void emit(int b)
{
	if (U.cc.bc_len < BC_MAX)
		U.cc.bc[U.cc.bc_len++] = (unsigned char)b;
	else
		U.cc.err = 1;
}

static void emit16(int v)
{
	emit(v & 0xFF);
	emit((v >> 8) & 0xFF);
}

static void patch16(int pos, int v)
{
	U.cc.bc[pos] = (unsigned char)(v & 0xFF);
	U.cc.bc[pos + 1] = (unsigned char)((v >> 8) & 0xFF);
}

/* ---- lexer: stream the source, one lookahead char ---- */


static int getch(void)
{
	char c;

	if (U.cc.pb != -2) {
		int r = U.cc.pb;

		U.cc.pb = -2;
		return r;
	}
	if (U.cc.eof_seen)
		return -1;
	if (sys_read(U.cc.infd, &c, 1) <= 0) {
		U.cc.eof_seen = 1;
		return -1;
	}
	return (unsigned char)c;
}

#define T_EOF  0
#define T_NUM  256
#define T_VAR  257
#define T_STR  258
#define T_PRINT 259
#define T_IF   260
#define T_ELSE 261
#define T_WHILE 262
#define T_EQOP 263
#define T_NEOP 264
#define T_LEOP 265
#define T_GEOP 266
#define T_WAIT 267
#define T_PIN  268


static void cc_next_tok(void)
{
	int c, i;

	if (U.cc.err) {
		U.cc.tok = T_EOF;
		return;
	}
	do {
		c = getch();
	} while (c == ' ' || c == '\t' || c == '\r' || c == '\n');
	if (c < 0) {
		U.cc.tok = T_EOF;
		return;
	}
	if (c >= '0' && c <= '9') {
		int v = 0;

		while (c >= '0' && c <= '9') {
			v = v * 10 + (c - '0');
			c = getch();
		}
		U.cc.pb = c;
		U.cc.tokval = v;
		U.cc.tok = T_NUM;
		return;
	}
	if ((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z')) {
		i = 0;
		while ((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') ||
		       (c >= '0' && c <= '9')) {
			if (i < (int)sizeof(U.cc.tokbuf) - 1)
				U.cc.tokbuf[i++] = (char)c;
			c = getch();
		}
		U.cc.pb = c;
		U.cc.tokbuf[i] = 0;
		if (i == 1 && U.cc.tokbuf[0] >= 'a' && U.cc.tokbuf[0] <= 'z') {
			U.cc.tokvar = U.cc.tokbuf[0] - 'a';
			U.cc.tok = T_VAR;
		} else if (ucmp(U.cc.tokbuf, "print") == 0)
			U.cc.tok = T_PRINT;
		else if (ucmp(U.cc.tokbuf, "if") == 0)
			U.cc.tok = T_IF;
		else if (ucmp(U.cc.tokbuf, "else") == 0)
			U.cc.tok = T_ELSE;
		else if (ucmp(U.cc.tokbuf, "while") == 0)
			U.cc.tok = T_WHILE;
		else if (ucmp(U.cc.tokbuf, "wait") == 0)
			U.cc.tok = T_WAIT;
		else if (ucmp(U.cc.tokbuf, "pin") == 0)
			U.cc.tok = T_PIN;
		else
			U.cc.err = 1;
		return;
	}
	if (c == '"') {
		i = 0;
		for (;;) {
			c = getch();
			if (c < 0 || c == '"')
				break;
			if (c == '\\') {
				c = getch();
				if (c == 'n')
					c = '\n';
				else if (c == 't')
					c = '\t';
			}
			if (i < (int)sizeof(U.cc.strbuf) - 1)
				U.cc.strbuf[i++] = (char)c;
		}
		U.cc.strbuf[i] = 0;
		U.cc.str_len = i;
		U.cc.tok = T_STR;
		return;
	}
	if (c == '=') {
		int n = getch();

		if (n == '=') {
			U.cc.tok = T_EQOP;
			return;
		}
		U.cc.pb = n;
		U.cc.tok = '=';
		return;
	}
	if (c == '!') {
		int n = getch();

		if (n == '=') {
			U.cc.tok = T_NEOP;
			return;
		}
		U.cc.err = 1;
		return;
	}
	if (c == '<') {
		int n = getch();

		if (n == '=') {
			U.cc.tok = T_LEOP;
			return;
		}
		U.cc.pb = n;
		U.cc.tok = '<';
		return;
	}
	if (c == '>') {
		int n = getch();

		if (n == '=') {
			U.cc.tok = T_GEOP;
			return;
		}
		U.cc.pb = n;
		U.cc.tok = '>';
		return;
	}
	U.cc.tok = c;	/* + - * / % ( ) { } ; */
}

/* ---- parser: recursive descent, single pass ---- */

static void parse_expr(void);

static void expect(int t)
{
	if (U.cc.tok != t)
		U.cc.err = 1;
	else
		cc_next_tok();
}

static void parse_factor(void)
{
	if (U.cc.err)
		return;
	if (U.cc.tok == T_NUM) {
		emit(OP_PUSH);
		emit16(U.cc.tokval);
		cc_next_tok();
	} else if (U.cc.tok == T_VAR) {
		emit(OP_LOAD);
		emit(U.cc.tokvar);
		cc_next_tok();
	} else if (U.cc.tok == '(') {
		cc_next_tok();
		parse_expr();
		expect(')');
	} else if (U.cc.tok == '-') {
		cc_next_tok();
		parse_factor();
		emit(OP_NEG);
	} else {
		U.cc.err = 1;
	}
}

static void parse_term(void)
{
	parse_factor();
	while (U.cc.tok == '*' || U.cc.tok == '/' || U.cc.tok == '%') {
		int op = U.cc.tok;

		cc_next_tok();
		parse_factor();
		emit(op == '*' ? OP_MUL : op == '/' ? OP_DIV : OP_MOD);
	}
}

static void parse_add(void)
{
	parse_term();
	while (U.cc.tok == '+' || U.cc.tok == '-') {
		int op = U.cc.tok;

		cc_next_tok();
		parse_term();
		emit(op == '+' ? OP_ADD : OP_SUB);
	}
}

static void parse_expr(void)
{
	int op;

	parse_add();
	if (U.cc.err)
		return;
	if (U.cc.tok == T_EQOP || U.cc.tok == T_NEOP || U.cc.tok == '<' || U.cc.tok == '>' ||
	    U.cc.tok == T_LEOP || U.cc.tok == T_GEOP) {
		op = U.cc.tok;
		cc_next_tok();
		parse_add();
		emit(op == T_EQOP ? OP_EQ : op == T_NEOP ? OP_NE :
		     op == '<' ? OP_LT : op == '>' ? OP_GT :
		     op == T_LEOP ? OP_LE : OP_GE);
	}
}

static void parse_stmt(void)
{
	if (U.cc.err)
		return;
	if (U.cc.tok == T_VAR) {
		int v = U.cc.tokvar;

		cc_next_tok();
		expect('=');
		parse_expr();
		emit(OP_STORE);
		emit(v);
		expect(';');
	} else if (U.cc.tok == T_PRINT) {
		int i;

		cc_next_tok();
		if (U.cc.tok == T_STR) {
			emit(OP_PSTR);
			emit(U.cc.str_len);
			for (i = 0; i < U.cc.str_len; i++)
				emit(U.cc.strbuf[i]);
			cc_next_tok();
		} else {
			parse_expr();
			emit(OP_PRINT);
		}
		expect(';');
	} else if (U.cc.tok == T_IF) {
		int jz, jmp;

		cc_next_tok();
		expect('(');
		parse_expr();
		expect(')');
		emit(OP_JZ);
		jz = U.cc.bc_len;
		emit16(0);
		parse_stmt();
		if (U.cc.tok == T_ELSE) {
			emit(OP_JMP);
			jmp = U.cc.bc_len;
			emit16(0);
			patch16(jz, U.cc.bc_len);
			cc_next_tok();
			parse_stmt();
			patch16(jmp, U.cc.bc_len);
		} else {
			patch16(jz, U.cc.bc_len);
		}
	} else if (U.cc.tok == T_WHILE) {
		int start = U.cc.bc_len, jz;

		cc_next_tok();
		expect('(');
		parse_expr();
		expect(')');
		emit(OP_JZ);
		jz = U.cc.bc_len;
		emit16(0);
		parse_stmt();
		emit(OP_JMP);
		emit16(start);
		patch16(jz, U.cc.bc_len);
	} else if (U.cc.tok == T_WAIT) {
		cc_next_tok();
		parse_expr();
		emit(OP_WAIT);
		expect(';');
	} else if (U.cc.tok == T_PIN) {
		cc_next_tok();
		parse_expr();
		expect(',');
		parse_expr();
		emit(OP_PINW);
		expect(';');
	} else if (U.cc.tok == '{') {
		cc_next_tok();
		while (U.cc.tok != '}' && U.cc.tok != T_EOF && !U.cc.err)
			parse_stmt();
		expect('}');
	} else if (U.cc.tok == ';') {
		cc_next_tok();
	} else {
		U.cc.err = 1;
	}
}


static int app_cc(const char *args)
{
	int ofd, i, dot;

	U.cc.pb = -2;

	argcpy(U.cc.srcname, args, (int)sizeof(U.cc.srcname));
	if (U.cc.srcname[0] == 0) {
		uputs("usage: cc file.c\n");
		return 1;
	}
	U.cc.infd = sys_open(U.cc.srcname);
	if (U.cc.infd < 0) {
		uputs("cc: no such file\n");
		return 1;
	}
	cc_next_tok();
	while (U.cc.tok != T_EOF && !U.cc.err)
		parse_stmt();
	emit(OP_HALT);
	sys_close(U.cc.infd);
	if (U.cc.err) {
		uputs("cc: error\n");
		return 1;
	}
	/* output name: replace a trailing .c with .out,
	 * otherwise append .out */
	strcpy(U.cc.outname, U.cc.srcname);
	dot = -1;
	for (i = 0; U.cc.outname[i]; i++)
		if (U.cc.outname[i] == '.')
			dot = i;
	if (dot >= 0 && U.cc.outname[dot + 1] == 'c' && U.cc.outname[dot + 2] == 0)
		U.cc.outname[dot] = 0;
	if ((int)strlen(U.cc.outname) > (int)sizeof(U.cc.outname) - 5) {
		uputs("cc: name too long\n");
		return 1;
	}
	ucpy(U.cc.outname + strlen(U.cc.outname), ".out");	/* literal is in flash */
	ofd = sys_openw(U.cc.outname, 0);
	if (ofd < 0) {
		uputs("cc: cannot create out\n");
		return 1;
	}
	{
		char hdr[2];

		hdr[0] = 'U';
		hdr[1] = 'B';
		sys_write(ofd, hdr, 2);
	}
	sys_write(ofd, (char *)U.cc.bc, U.cc.bc_len);
	sys_close(ofd);
	return 0;
}

/* linaX(uno) vm: runs 'UB' bytecode files produced by cc.
 * Normally launched by the kernel's exec when a /tmp file
 * with the 'UB' magic is executed; argv is the file U.vm.path.
 * Stack machine, int16 arithmetic, variables a-z. */


#define CODE_MAX 96
#define STK_MAX 10


static int push(int v)
{
	if (U.vm.sp >= STK_MAX)
		return -1;
	U.vm.st[U.vm.sp++] = v;
	return 0;
}

static int pop(void)
{
	return U.vm.sp > 0 ? U.vm.st[--U.vm.sp] : 0;
}


static int app_vm(const char *args)
{
	int fd, n, pc;
	char hdr[2];

	argcpy(U.vm.path, args, (int)sizeof(U.vm.path));
	if (U.vm.path[0] == 0) {
		uputs("vm: no file\n");
		return 1;
	}
	fd = sys_open(U.vm.path);
	if (fd < 0) {
		uputs("vm: no such file\n");
		return 1;
	}
	if (sys_read(fd, hdr, 2) != 2 || hdr[0] != 'U' || hdr[1] != 'B') {
		uputs("vm: bad magic\n");
		return 1;
	}
	U.vm.code_len = 0;
	while ((n = sys_read(fd, (char *)U.vm.code + U.vm.code_len,
			     CODE_MAX - U.vm.code_len)) > 0)
		U.vm.code_len += n;
	sys_close(fd);
	if (U.vm.code_len >= CODE_MAX) {
		uputs("vm: too big\n");
		return 1;
	}
	pc = 0;
	U.vm.sp = 0;
	while (pc >= 0 && pc < U.vm.code_len) {
		int op = U.vm.code[pc++];
		int a, b;

		switch (op) {
		case OP_HALT:
			return 0;
		case OP_PUSH:
			a = U.vm.code[pc] | (U.vm.code[pc + 1] << 8);
			pc += 2;
			if (push(a) < 0)
				goto stkerr;
			break;
		case OP_LOAD:
			if (push(U.vm.vars[U.vm.code[pc++]]) < 0)
				goto stkerr;
			break;
		case OP_STORE:
			U.vm.vars[U.vm.code[pc++]] = pop();
			break;
		case OP_ADD: b = pop(); a = pop(); push(a + b); break;
		case OP_SUB: b = pop(); a = pop(); push(a - b); break;
		case OP_MUL: b = pop(); a = pop(); push(a * b); break;
		case OP_DIV:
			b = pop(); a = pop();
			if (b == 0) {
				uputs("vm: div0\n");
				return 1;
			}
			push(a / b);
			break;
		case OP_MOD:
			b = pop(); a = pop();
			if (b == 0) {
				uputs("vm: div0\n");
				return 1;
			}
			push(a % b);
			break;
		case OP_NEG: push(-pop()); break;
		case OP_EQ: b = pop(); a = pop(); push(a == b); break;
		case OP_NE: b = pop(); a = pop(); push(a != b); break;
		case OP_LT: b = pop(); a = pop(); push(a < b); break;
		case OP_GT: b = pop(); a = pop(); push(a > b); break;
		case OP_LE: b = pop(); a = pop(); push(a <= b); break;
		case OP_GE: b = pop(); a = pop(); push(a >= b); break;
		case OP_JZ:
			a = U.vm.code[pc] | (U.vm.code[pc + 1] << 8);
			pc += 2;
			if (pop() == 0)
				pc = a;
			break;
		case OP_JMP:
			pc = U.vm.code[pc] | (U.vm.code[pc + 1] << 8);
			break;
		case OP_PRINT:
			uputd(pop());
			uputs("\n");
			break;
		case OP_PSTR:
			a = U.vm.code[pc++];
			sys_write(1, (char *)U.vm.code + pc, a);
			pc += a;
			uputs("\n");
			break;
		case OP_WAIT:	/* operand in milliseconds */
			a = pop();
			sys_sleep((unsigned int)(a > 0 ? a / 10 : 0));
			break;
		case OP_PINW:	/* pin p, v: output mode, then write */
			b = pop(); a = pop();
			sys_gpio(a, 2, 0);
			sys_gpio(a, 3, b);
			break;
		default:
			uputs("vm: bad op\n");
			return 1;
		}
	}
	return 0;

stkerr:
	uputs("vm: stack overflow\n");
	return 1;
}

/* gpio: drive one Arduino-numbered pin.
 * gpio_usage: gpio <pin> in|inpull|out|hi|lo|read
 * <pin> is 0..19, or A0..A5 for pins 14..19. hi and lo
 * switch the pin to output first. read prints 0 or 1. */


static int gpio_next_tok(int i, char *tok, int max)
{
	int n = 0;

	while (U.g.arg[i] == ' ')
		i++;
	while (U.g.arg[i] && U.g.arg[i] != ' ' && n < max - 1)
		tok[n++] = U.g.arg[i++];
	tok[n] = 0;
	return i;
}

static int parse_pin(const char *t)
{
	int v = 0;

	if (t[0] == 'A' || t[0] == 'a') {
		if (t[1] < '0' || t[1] > '5' || t[2])
			return -1;
		return 14 + (t[1] - '0');
	}
	if (!*t)
		return -1;
	while (*t) {
		if (*t < '0' || *t > '9')
			return -1;
		v = v * 10 + (*t++ - '0');
	}
	return v;
}

static int gpio_usage(void)
{
	uputs("gpio_usage: gpio <pin> in|inpull|out|hi|lo|read\n");
	return 1;
}

static int app_gpio(const char *args)
{
	int i, pin, op, val = 0, r;

	argcpy(U.g.arg, args, (int)sizeof(U.g.arg));
	i = gpio_next_tok(0, U.g.tok, sizeof(U.g.tok));
	gpio_next_tok(i, U.g.tok1, sizeof(U.g.tok1));
	pin = parse_pin(U.g.tok);
	if (pin < 0 || !U.g.tok1[0])
		return gpio_usage();
	if (ucmp(U.g.tok1, "in") == 0)
		op = 0;
	else if (ucmp(U.g.tok1, "inpull") == 0)
		op = 1;
	else if (ucmp(U.g.tok1, "out") == 0)
		op = 2;
	else if (ucmp(U.g.tok1, "hi") == 0) {
		op = 3;
		val = 1;
	} else if (ucmp(U.g.tok1, "lo") == 0)
		op = 3;
	else if (ucmp(U.g.tok1, "read") == 0)
		op = 4;
	else
		return gpio_usage();
	if (op == 3 && sys_gpio(pin, 2, 0) < 0) {
		uputs("gpio: error\n");
		return 1;
	}
	r = sys_gpio(pin, op, val);
	if (r < 0) {
		uputs("gpio: error\n");
		return 1;
	}
	if (op == 4) {
		uputd(r);
		uputs("\n");
	}
	return 0;
}

/* i2c: probe and transfer on the I2C bus (A4 = SDA,
 * A5 = SCL).
 * i2c_usage: i2c scan
 *        i2c w <addr> <byte> [byte...]
 *        i2c r <addr> <count>
 * Numbers are decimal, or hex with a 0x prefix. Read
 * data is printed as lowercase hex bytes. */


static int i2c_next_tok(int i, char *t, int max)
{
	int n = 0;

	while (U.g.arg[i] == ' ')
		i++;
	while (U.g.arg[i] && U.g.arg[i] != ' ' && n < max - 1)
		t[n++] = U.g.arg[i++];
	t[n] = 0;
	return i;
}

static int parse_num(const char *t)
{
	int v = 0, hex = 0;

	if (t[0] == '0' && (t[1] == 'x' || t[1] == 'X')) {
		hex = 1;
		t += 2;
	}
	if (!*t)
		return -1;
	while (*t) {
		int d;

		if (*t >= '0' && *t <= '9')
			d = *t - '0';
		else if (hex && *t >= 'a' && *t <= 'f')
			d = *t - 'a' + 10;
		else if (hex && *t >= 'A' && *t <= 'F')
			d = *t - 'A' + 10;
		else
			return -1;
		v = v * (hex ? 16 : 10) + d;
		t++;
	}
	return v;
}

static void putc1(char c)
{
	sys_write(1, &c, 1);
}

static void putx2(int v)
{
	int hi = (v >> 4) & 15, lo = v & 15;

	putc1((char)(hi < 10 ? '0' + hi : 'a' + hi - 10));
	putc1((char)(lo < 10 ? '0' + lo : 'a' + lo - 10));
}

static int i2c_usage(void)
{
	uputs("i2c_usage: i2c scan | i2c w <addr> <byte>... | i2c r <addr> <n>\n");
	return 1;
}

static int no_ack(void)
{
	uputs("i2c: no ack\n");
	return 1;
}

static int app_i2c(const char *args)
{
	int i, addr, n, b;

	argcpy(U.g.arg, args, (int)sizeof(U.g.arg));
	i = i2c_next_tok(0, U.g.tok, sizeof(U.g.tok));
	if (ucmp(U.g.tok, "scan") == 0) {
		int found = 0;

		uputs("i2c scan:");
		for (addr = 8; addr < 0x78; addr++) {
			if (sys_i2c(addr, U.g.buf, 0, U.g.buf, 0) == 0) {
				uputs(" 0x");
				putx2(addr);
				found++;
			}
		}
		if (!found)
			uputs(" none");
		uputs("\n");
		return 0;
	}
	if (ucmp(U.g.tok, "w") == 0) {
		i = i2c_next_tok(i, U.g.tok, sizeof(U.g.tok));
		addr = parse_num(U.g.tok);
		n = 0;
		for (;;) {
			i = i2c_next_tok(i, U.g.tok, sizeof(U.g.tok));
			if (!U.g.tok[0] || n >= 16)
				break;
			b = parse_num(U.g.tok);
			if (b < 0 || b > 255)
				return i2c_usage();
			U.g.buf[n++] = (char)b;
		}
		if (addr < 0 || addr > 0x7F || n == 0)
			return i2c_usage();
		if (sys_i2c(addr, U.g.buf, n, U.g.buf, 0) < 0)
			return no_ack();
		return 0;
	}
	if (ucmp(U.g.tok, "r") == 0) {
		i = i2c_next_tok(i, U.g.tok, sizeof(U.g.tok));
		addr = parse_num(U.g.tok);
		i = i2c_next_tok(i, U.g.tok, sizeof(U.g.tok));
		n = parse_num(U.g.tok);
		if (addr < 0 || addr > 0x7F || n < 1 || n > 16)
			return i2c_usage();
		if (sys_i2c(addr, U.g.buf, 0, U.g.buf, n) < 0)
			return no_ack();
		for (i = 0; i < n; i++) {
			if (i)
				putc1(' ');
			putx2((unsigned char)U.g.buf[i]);
		}
		putc1('\n');
		return 0;
	}
	return i2c_usage();
}

/* sleep: wait for the given number of 10 ms ticks.
 * usage: sleep <ticks>   (sleep 100 = 1 second)
 * The kernel's sys_sleep compares wake times with a
 * 16-bit signed difference, so one call can sleep at
 * most 32767 ticks; long waits are split into chunks. */


static int app_sleep(const char *args)
{
	int i = 0, any = 0;
	unsigned long v = 0;

	argcpy(U.g.arg, args, (int)sizeof(U.g.arg));
	while (U.g.arg[i] == ' ')
		i++;
	while (U.g.arg[i] >= '0' && U.g.arg[i] <= '9') {
		v = v * 10 + (unsigned long)(U.g.arg[i++] - '0');
		any = 1;
	}
	if (!any) {
		uputs("usage: sleep <ticks> (1 tick = 10 ms)\n");
		return 1;
	}
	while (v > 0) {
		unsigned int chunk = v > 30000UL ? 30000 : (unsigned int)v;

		sys_sleep(chunk);
		v -= chunk;
	}
	return 0;
}


int main(void)
{
	const char *args;
	char *p;

	sys_argv(bb_argv, sizeof(bb_argv));
	p = bb_argv;
	while (*p && *p != ' ')
		p++;
	if (*p == ' ')
		*p++ = 0;
	args = p;
	if (ucmp(bb_argv, "ls") == 0)
		return app_ls(args);
	if (ucmp(bb_argv, "cat") == 0)
		return app_cat(args);
	if (ucmp(bb_argv, "echo") == 0)
		return app_echo(args);
	if (ucmp(bb_argv, "uname") == 0)
		return app_uname(args);
	if (ucmp(bb_argv, "ps") == 0)
		return app_ps(args);
	if (ucmp(bb_argv, "cc") == 0)
		return app_cc(args);
	if (ucmp(bb_argv, "vm") == 0)
		return app_vm(args);
	if (ucmp(bb_argv, "gpio") == 0)
		return app_gpio(args);
	if (ucmp(bb_argv, "i2c") == 0)
		return app_i2c(args);
	if (ucmp(bb_argv, "sleep") == 0)
		return app_sleep(args);
	uputs("busybox: unknown applet\n");
	return 1;
}

